import React, { useState } from 'react';
import { db } from '../config/firebase';
import { collection, addDoc } from 'firebase/firestore';

const TechPortal = ({ addMaintenanceRecord }) => {
  const [techFormData, setTechFormData] = useState({
    panelId: '',
    inspectionType: 'Routine Check',
    notes: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [submitError, setSubmitError] = useState(null);

  const handleSubmitTechReport = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitError(null);

    try {
      // Add to Firestore
      const reportData = {
        panelId: techFormData.panelId,
        type: techFormData.inspectionType,
        technicianName: "Tech User", // This would come from user profile
        notes: techFormData.notes,
        status: 'pending',
        timestamp: new Date(),
      };

      // Save to Firestore
      const docRef = await addDoc(collection(db, 'maintenance_records'), reportData);

      // Add to local state too
      addMaintenanceRecord({
        id: docRef.id,
        ...reportData
      });

      // Reset form
      setTechFormData({
        panelId: '',
        inspectionType: 'Routine Check',
        notes: ''
      });

      setSubmitSuccess(true);
      setTimeout(() => {
        setSubmitSuccess(false);
      }, 3000);

    } catch (error) {
      console.error('Error submitting report:', error);
      setSubmitError('Failed to submit report. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="tech-portal">
      <h2>Technician Portal</h2>
      <p>Submit inspection reports for solar panels.</p>

      {submitSuccess && (
        <div className="success-message">
          Report submitted successfully! The record has been added to maintenance history.
        </div>
      )}

      {submitError && (
        <div className="error-message">{submitError}</div>
      )}

      <form className="inspection-form" onSubmit={handleSubmitTechReport}>
        <div className="form-group">
          <label>Panel ID</label>
          <input 
            type="text" 
            placeholder="Enter Panel ID"
            value={techFormData.panelId}
            onChange={(e) => setTechFormData({...techFormData, panelId: e.target.value})}
            required
          />
        </div>
        <div className="form-group">
          <label>Inspection Type</label>
          <select
            value={techFormData.inspectionType}
            onChange={(e) => setTechFormData({...techFormData, inspectionType: e.target.value})}
          >
            <option>Routine Check</option>
            <option>Maintenance</option>
            <option>Repair</option>
            <option>Emergency Service</option>
          </select>
        </div>
        <div className="form-group">
          <label>Notes</label>
          <textarea 
            placeholder="Enter inspection details"
            value={techFormData.notes}
            onChange={(e) => setTechFormData({...techFormData, notes: e.target.value})}
            required
          ></textarea>
        </div>
        <div className="form-actions">
          <button 
            type="submit" 
            className="submit-btn"
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Submitting...' : 'Submit Report'}
          </button>
          <button 
            type="button" 
            className="clear-btn" 
            onClick={() => setTechFormData({
              panelId: '',
              inspectionType: 'Routine Check',
              notes: ''
            })}
            disabled={isSubmitting}
          >
            Clear Form
          </button>
        </div>
      </form>
    </div>
  );
};

export default TechPortal;
